let cultura = flow.get("cultura");

msg.payload = {
    tab: "Informações"
};

msg.cultura = cultura;

return msg;

flow.set("umidade", 40);

msg.payload = 40;

return msg;

flow.set("temperatura", 27);

msg.payload = 27;

return msg;

flow.set("ph", 6.2);

msg.payload = 6.2;

return msg;

flow.set("ec", 1.4);

msg.payload = 1.4;

return msg;

let cultura = flow.get("cultura");

if (cultura) {
    cultura = cultura.toString().toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "");
}

let umidade = flow.get("umidade");
let temperaturaSolo = flow.get("temperatura");
let ph = flow.get("ph");
let ec = flow.get("ec");
let n = flow.get("nitrogenio");
let p = flow.get("fosforo");
let k = flow.get("potassio");

let chuva = flow.get("chuva") || 0;
let temperaturaAr = flow.get("temperaturaAr") || 0;
let umidadeAr = flow.get("umidadeAr") || 0;
let vento = flow.get("vento") || 0;
let radiacaoSolar = flow.get("radiacaoSolar") || 0;

let culturas = {
    milho: { nome: "Milho", umMin: 60, umMax: 80, tempMin: 20, tempMax: 30, phMin: 5.5, phMax: 7.0, ecMin: 1.0, ecMax: 2.5, nMin: 20, nMax: 40, pMin: 15, pMax: 30, kMin: 80, kMax: 150 },
    soja: { nome: "Soja", umMin: 60, umMax: 70, tempMin: 20, tempMax: 30, phMin: 5.5, phMax: 6.8, ecMin: 1.0, ecMax: 2.0, nMin: null, nMax: null, pMin: 20, pMax: 40, kMin: 100, kMax: 200 },
    cafe: { nome: "Café", umMin: 60, umMax: 80, tempMin: 18, tempMax: 24, phMin: 5.5, phMax: 6.5, ecMin: 1.0, ecMax: 2.5, nMin: 30, nMax: 60, pMin: 20, pMax: 40, kMin: 100, kMax: 200 },
    cana: { nome: "Cana-de-açúcar", umMin: 60, umMax: 80, tempMin: 25, tempMax: 35, phMin: 5.5, phMax: 6.5, ecMin: 1.0, ecMax: 2.0, nMin: 60, nMax: 120, pMin: 30, pMax: 60, kMin: 100, kMax: 200 },
    morango: { nome: "Morango", umMin: 65, umMax: 80, tempMin: 15, tempMax: 25, phMin: 5.5, phMax: 6.5, ecMin: 1.2, ecMax: 2.0, nMin: 50, nMax: 100, pMin: 30, pMax: 60, kMin: 100, kMax: 200 },
    mandioca: { nome: "Mandioca", umMin: 50, umMax: 70, tempMin: 25, tempMax: 30, phMin: 5.0, phMax: 6.5, ecMin: 0.5, ecMax: 1.5, nMin: 10, nMax: 25, pMin: 10, pMax: 25, kMin: 80, kMax: 150 }
};

let ref = culturas[cultura];

if (!ref) {
    msg.payload = {
        cultura: "Não selecionada",
        total: 0,
        itens: ["Selecione uma cultura para gerar recomendações."]
    };
    return msg;
}

let itens = [];

if (umidade < ref.umMin) {
    if (chuva >= 10) {
        itens.push("💧 Solo seco, mas houve chuva. Reavaliar antes de irrigar.");
    } else {
        itens.push("💧 Umidade baixa. Irrigar 10 a 20 mm.");
    }
} else if (umidade > ref.umMax) {
    itens.push("💧 Umidade alta. Suspender irrigação.");
}

if (temperaturaSolo < ref.tempMin) {
    itens.push("🌡 Temperatura do solo baixa. Evitar excesso de irrigação.");
} else if (temperaturaSolo > ref.tempMax) {
    itens.push("🌡 Temperatura do solo alta. Usar cobertura vegetal/mulch.");
}

if (ph < ref.phMin) {
    itens.push("🧪 pH baixo. Avaliar aplicação de calcário.");
} else if (ph > ref.phMax) {
    itens.push("🧪 pH alto. Avaliar correção do solo.");
}

if (ec < ref.ecMin) {
    itens.push("⚡ EC baixa. Verificar adubação.");
} else if (ec > ref.ecMax) {
    itens.push("⚡ EC alta. Possível excesso de sais.");
}

if (ref.nMin !== null) {
    if (n < ref.nMin) itens.push("🌿 Nitrogênio baixo. Avaliar ureia ou nitrato.");
    else if (n > ref.nMax) itens.push("🌿 Nitrogênio alto. Reduzir adubação nitrogenada.");
}

if (p < ref.pMin) {
    itens.push("🪨 Fósforo baixo. Avaliar superfosfato.");
} else if (p > ref.pMax) {
    itens.push("🪨 Fósforo alto. Evitar adubação fosfatada.");
}

if (k < ref.kMin) {
    itens.push("🍌 Potássio baixo. Avaliar cloreto de potássio.");
} else if (k > ref.kMax) {
    itens.push("🍌 Potássio alto. Reduzir adubação potássica.");
}

if (vento > 25) {
    itens.push("💨 Vento elevado. Evitar pulverização.");
}

if (umidadeAr > 90) {
    itens.push("💧 Umidade do ar alta. Monitorar doenças fúngicas.");
}

if (umidadeAr < 40 && radiacaoSolar > 800) {
    itens.push("☀️ Ar seco e radiação alta. Risco de estresse hídrico.");
}

if (itens.length === 0) {
    itens.push("✅ Nenhuma ação corretiva necessária no momento.");
}

msg.payload = {
    cultura: ref.nome,
    total: itens.length,
    itens: itens
};

return msg;

// ==========================================
// AGROSYNK - HISTÓRICO REAL DE UMIDADE DO SOLO
// ==========================================
//
// CAMPO CORRETO:
// umidadeSolo = UMIDADE DO SOLO REAL
//
// NÃO usar umidadeSolo1 aqui,
// pois umidadeSolo1 representa UMIDADE DO AR.
// ==========================================

let historico = flow.get("historico30dias") || [];

// Verifica se existe histórico
if (!Array.isArray(historico) || historico.length === 0) {
    node.warn("Ainda não existem dados no histórico.");
    return null;
}

let pontos = [];

// ==========================================
// MONTAR PONTOS DO GRÁFICO
// ==========================================

historico.forEach(function(leitura) {

    if (
        leitura.dataHora &&
        leitura.umidadeSolo !== undefined &&
        leitura.umidadeSolo !== null
    ) {

        let data = new Date(
            leitura.dataHora.replace(" ", "T")
        );

        let valor = Number(leitura.umidadeSolo);

        if (
            !isNaN(data.getTime()) &&
            !isNaN(valor)
        ) {

            pontos.push({
                x: data.getTime(),
                y: valor
            });
        }
    }
});

// ==========================================
// VERIFICAÇÃO
// ==========================================

if (pontos.length === 0) {
    node.warn("Nenhum dado válido de umidade do solo encontrado.");
    return null;
}

// ==========================================
// ENVIAR PARA O UI_CHART
// ==========================================

msg.payload = [{
    series: ["Umidade do Solo"],
    data: [pontos],
    labels: [""]
}];

return msg;

// ==========================================
// AGROSYNK - SIMULAÇÃO CONTÍNUA DE pH
// DADO SIMULADO PARA DEMONSTRAÇÃO
// ==========================================

let ph = flow.get("phSimulado");

if (ph === undefined || ph === null) {
    ph = 6.20;
}

// Variação suave de aproximadamente -0.08 a +0.08
let variacao = (Math.random() - 0.5) * 0.16;

ph = ph + variacao;

// Limites da simulação
if (ph < 5.5) ph = 5.5;
if (ph > 7.0) ph = 7.0;

// Duas casas decimais para a variação aparecer no gráfico
ph = Number(ph.toFixed(2));

flow.set("phSimulado", ph);

msg.payload = ph;
msg.topic = "pH (Simulado)";

return msg;

// ==========================================
// AGROSYNK - HISTÓRICO REAL DE TEMPERATURA DO SOLO
// ==========================================
//
// CAMPO CORRETO:
// temperaturaSolo = TEMPERATURA DO SOLO REAL
//
// NÃO usar temperaturaSolo1 aqui,
// pois temperaturaSolo1 representa
// TEMPERATURA DO AR.
// ==========================================

let historico = flow.get("historico30dias") || [];

// Verifica se existe histórico
if (!Array.isArray(historico) || historico.length === 0) {
    node.warn("Ainda não existem dados no histórico.");
    return null;
}

let pontos = [];

// ==========================================
// MONTAR PONTOS DO GRÁFICO
// ==========================================

historico.forEach(function(leitura) {

    if (
        leitura.dataHora &&
        leitura.temperaturaSolo !== undefined &&
        leitura.temperaturaSolo !== null
    ) {

        let data = new Date(
            leitura.dataHora.replace(" ", "T")
        );

        let valor = Number(leitura.temperaturaSolo);

        if (
            !isNaN(data.getTime()) &&
            !isNaN(valor)
        ) {

            pontos.push({
                x: data.getTime(),
                y: valor
            });
        }
    }
});

// ==========================================
// VERIFICAÇÃO
// ==========================================

if (pontos.length === 0) {
    node.warn("Nenhum dado válido de temperatura do solo encontrado.");
    return null;
}

// ==========================================
// ENVIAR PARA O UI_CHART
// ==========================================

msg.payload = [{
    series: ["Temperatura do Solo"],
    data: [pontos],
    labels: [""]
}];

return msg;

let cultura = flow.get("cultura");

if (cultura) {
    cultura = cultura.toString().toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "");
}

let umidade = flow.get("umidade");
let ph = flow.get("ph");
let ec = flow.get("ec");

let culturas = {
    milho: { nome: "Milho", umidadeMin: 60, umidadeMax: 80, phMin: 5.5, phMax: 7.0, ecMin: 1.0, ecMax: 2.5 },
    soja: { nome: "Soja", umidadeMin: 60, umidadeMax: 75, phMin: 5.5, phMax: 6.8, ecMin: 1.0, ecMax: 2.0 },
    cafe: { nome: "Café", umidadeMin: 60, umidadeMax: 80, phMin: 5.5, phMax: 6.5, ecMin: 1.0, ecMax: 2.5 },
    cana: { nome: "Cana-de-açúcar", umidadeMin: 60, umidadeMax: 80, phMin: 5.5, phMax: 6.5, ecMin: 1.0, ecMax: 2.0 },
    morango: { nome: "Morango", umidadeMin: 65, umidadeMax: 80, phMin: 5.5, phMax: 6.5, ecMin: 1.2, ecMax: 2.0 },
    mandioca: { nome: "Mandioca", umidadeMin: 50, umidadeMax: 70, phMin: 5.0, phMax: 6.5, ecMin: 0.5, ecMax: 1.5 }
};

let ref = culturas[cultura];

if (!ref) {
    msg.payload = {
        cor: "#9E9E9E",
        icone: "⚪",
        status: "Sem cultura selecionada",
        descricao: "Selecione uma cultura para iniciar a análise.",
        detalhes: ""
    };
    return msg;
}

let alertas = [];

if (umidade < ref.umidadeMin) {
    alertas.push("💧 Umidade abaixo do ideal para " + ref.nome + ".\n➡ Aumentar irrigação.");
} else if (umidade > ref.umidadeMax) {
    alertas.push("💧 Umidade acima do ideal para " + ref.nome + ".\n➡ Reduzir irrigação e verificar drenagem.");
}

if (ph < ref.phMin) {
    alertas.push("🧪 pH abaixo do ideal para " + ref.nome + ".\n➡ Avaliar correção com calcário.");
} else if (ph > ref.phMax) {
    alertas.push("🧪 pH acima do ideal para " + ref.nome + ".\n➡ Avaliar correção do solo.");
}

if (ec < ref.ecMin) {
    alertas.push("⚡ EC abaixo do ideal para " + ref.nome + ".\n➡ Verificar necessidade de adubação.");
} else if (ec > ref.ecMax) {
    alertas.push("⚡ EC acima do ideal para " + ref.nome + ".\n➡ Possível excesso de sais/fertilizantes.");
}

if (alertas.length === 0) {
    msg.payload = {
        cor: "#2E7D32",
        icone: "🟢",
        status: "Saudável",
        descricao: "Todos os parâmetros estão dentro da faixa ideal para " + ref.nome + ".",
        detalhes: "✅ Nenhuma ação corretiva necessária no momento."
    };
} else if (alertas.length === 1) {
    msg.payload = {
        cor: "#F9A825",
        icone: "🟡",
        status: "Atenção",
        descricao: "Foi detectado 1 parâmetro fora da faixa ideal.",
        detalhes: alertas.join("\n\n")
    };
} else {
    msg.payload = {
        cor: "#C62828",
        icone: "🔴",
        status: "Crítico",
        descricao: "Foram detectados " + alertas.length + " parâmetros fora da faixa ideal.",
        detalhes: alertas.join("\n\n")
    };
}

return msg;

let saude = flow.get("saudeLavoura") || 65;

let status = "";
let cor = "";
let icone = "";

if (saude >= 70) {
    status = "SAUDÁVEL";
    cor = "#2E7D32";
    icone = "🟢";
} else if (saude >= 40) {
    status = "ATENÇÃO";
    cor = "#F9A825";
    icone = "🟡";
} else {
    status = "CRÍTICO";
    cor = "#C62828";
    icone = "🔴";
}

msg.payload = {
    saude: saude,
    status: status,
    cor: cor,
    icone: icone
};

return msg;

let n = 25;

flow.set("nitrogenio", n);

msg.payload = n;

return msg;

let p = 18;

flow.set("fosforo", p);

msg.payload = p;

return msg;

let k = 90;

flow.set("potassio", k);

msg.payload = k;

return msg;

// ==========================================
// AGROSYNK - CHUVA ACUMULADA REAL
// DADO REAL DA ESTAÇÃO METEOROLÓGICA
// ==========================================

let historico = flow.get("historico30dias") || [];

if (!Array.isArray(historico) || historico.length === 0) {
    node.warn("Ainda não existem dados reais da estação.");
    return null;
}

// Pega a leitura mais recente
let ultima = historico[historico.length - 1];

// Chuva acumulada enviada pela estação
let chuvaAcumulada = Number(ultima.chuvaAcumulada);

if (isNaN(chuvaAcumulada)) {
    node.warn("Valor de chuva acumulada inválido.");
    return null;
}

// Salva para uso em alertas, relatórios e outros componentes
flow.set("chuva", chuvaAcumulada);
flow.set("chuvaAcumulada", chuvaAcumulada);

// Envia o valor para o gauge
msg.payload = chuvaAcumulada;
msg.topic = "Chuva Acumulada";

return msg;

// ==========================================
// AGROSYNK - TEMPERATURA DO AR REAL
//
// IMPORTANTE:
// temperaturaSolo1 é o nome legado.
// Esse campo representa TEMPERATURA DO AR.
// ==========================================

let historico = flow.get("historico30dias") || [];

if (!Array.isArray(historico) || historico.length === 0) {
    node.warn("Ainda não existem dados reais da estação.");
    return null;
}

// Pega a leitura mais recente
let ultima = historico[historico.length - 1];

let temperaturaAr = Number(ultima.temperaturaSolo1);

if (isNaN(temperaturaAr)) {
    node.warn("Temperatura do ar inválida.");
    return null;
}

// Salva para os outros componentes do sistema
flow.set("temperaturaAr", temperaturaAr);

// Envia para o gauge
msg.payload = temperaturaAr;
msg.topic = "Temperatura do Ar";

return msg;

// ==========================================
// AGROSYNK - UMIDADE DO AR REAL
//
// IMPORTANTE:
// umidadeSolo1 é o nome legado.
// Esse campo representa UMIDADE DO AR.
// ==========================================

let historico = flow.get("historico30dias") || [];

if (!Array.isArray(historico) || historico.length === 0) {
    node.warn("Ainda não existem dados reais da estação.");
    return null;
}

// Pega a leitura mais recente
let ultima = historico[historico.length - 1];

let umidadeAr = Number(ultima.umidadeSolo1);

if (isNaN(umidadeAr)) {
    node.warn("Umidade do ar inválida.");
    return null;
}

// Salva para os outros componentes do sistema
flow.set("umidadeAr", umidadeAr);

// Envia para o gauge
msg.payload = umidadeAr;
msg.topic = "Umidade do Ar";

return msg;

// ==========================================
// AGROSYNK - VELOCIDADE DO VENTO
// DADO SIMULADO PARA DEMONSTRAÇÃO
// ==========================================

let vento = flow.get("ventoSimulado");

// Valor inicial
if (vento === undefined || vento === null) {
    vento = 12.0;
}

// Variação contínua e suave
// Aproximadamente -1.5 a +1.5 km/h
let variacao = (Math.random() - 0.5) * 3;

vento = vento + variacao;

// Limites da simulação
if (vento < 3) vento = 3;
if (vento > 30) vento = 30;

// Uma casa decimal
vento = Number(vento.toFixed(1));

// Salva o valor simulado
flow.set("ventoSimulado", vento);

// Mantém também a variável que o restante
// do AgroSynk já utiliza
flow.set("vento", vento);

// Envia para o gauge
msg.payload = vento;
msg.topic = "Velocidade do Vento (Simulado)";

return msg;

// ==========================================
// AGROSYNK - DIREÇÃO DO VENTO
// DADO SIMULADO PARA DEMONSTRAÇÃO
// ==========================================

// Direções possíveis
let direcoes = [
    "N",
    "NE",
    "E",
    "SE",
    "S",
    "SO",
    "O",
    "NO"
];

// Recupera a direção anterior
let indice = flow.get("direcaoVentoIndice");

// Começa em Nordeste
if (indice === undefined || indice === null) {
    indice = 1;
}

// ==========================================
// VARIAÇÃO DA DIREÇÃO
// ==========================================
//
// Na maior parte das atualizações,
// permanece ou muda apenas para uma
// direção vizinha.
// ==========================================

let sorteio = Math.random();

if (sorteio < 0.25) {

    // Gira uma posição para a esquerda
    indice--;

} else if (sorteio > 0.75) {

    // Gira uma posição para a direita
    indice++;
}

// Corrige os extremos
if (indice < 0) {
    indice = direcoes.length - 1;
}

if (indice >= direcoes.length) {
    indice = 0;
}

let direcao = direcoes[indice];

// Salva para a próxima atualização
flow.set("direcaoVentoIndice", indice);

// Variável usada pelo AgroSynk
flow.set("direcaoVento", direcao);

// Saída para o template
msg.payload = direcao;
msg.topic = "Direção do Vento (Simulada)";

return msg;

// ==========================================
// AGROSYNK - RADIAÇÃO SOLAR
// DADO SIMULADO PARA DEMONSTRAÇÃO
// ==========================================

let radiacao = flow.get("radiacaoSolarSimulada");

// Valor inicial da demonstração
if (radiacao === undefined || radiacao === null) {
    radiacao = 650;
}

// ==========================================
// VARIAÇÃO SUAVE
// ==========================================

// Varia aproximadamente -25 a +25 W/m²
let variacao = (Math.random() - 0.5) * 50;

radiacao = radiacao + variacao;

// Limites definidos apenas para a simulação
if (radiacao < 300) radiacao = 300;
if (radiacao > 1000) radiacao = 1000;

// Número inteiro
radiacao = Math.round(radiacao);

// Salva o valor para a próxima atualização
flow.set("radiacaoSolarSimulada", radiacao);

// Mantém também a variável que o restante
// do AgroSynk utiliza
flow.set("radiacaoSolar", radiacao);

// Envia para o gauge
msg.payload = radiacao;
msg.topic = "Radiação Solar (Simulada)";

return msg;

let chuva = flow.get("chuva") || 0;
let temp = flow.get("temperaturaAr") || 0;
let umidade = flow.get("umidadeAr") || 0;
let vento = flow.get("vento") || 0;
let radiacao = flow.get("radiacaoSolar") || 0;

let status = "Clima Favorável";
let cor = "#2E7D32";
let mensagem = [];
let tendencia = "Condições estáveis nas próximas horas.";

if (temp > 35) {
    mensagem.push("🌡 Temperatura elevada.");
    status = "Atenção Climática";
    cor = "#F9A825";
}

if (umidade < 40) {
    mensagem.push("💧 Umidade do ar baixa.");
    status = "Atenção Climática";
    cor = "#F9A825";
}

if (vento > 30) {
    mensagem.push("💨 Ventos fortes.");
    status = "Atenção Climática";
    cor = "#F9A825";
}

if (chuva > 30) {
    mensagem.push("🌧 Chuva intensa.");
    status = "Atenção Climática";
    cor = "#F9A825";
}

if (radiacao > 1000) {
    mensagem.push("☀ Radiação solar elevada.");
    status = "Atenção Climática";
    cor = "#F9A825";
}

if (vento > 45 || temp > 38 || umidade < 25 || radiacao > 1100) {
    status = "Condição Crítica";
    cor = "#C62828";
}

if (mensagem.length === 0) {
    mensagem.push("✅ Condições adequadas para o manejo agrícola.");
}

if (chuva > 10) {
    tendencia = "Solo tende a permanecer úmido nas próximas horas.";
}

if (vento > 25) {
    tendencia = "Evitar pulverização devido ao vento.";
}

if (temp > 32) {
    tendencia = "Temperatura elevada pode aumentar a evaporação.";
}

msg.payload = {
    status: status,
    cor: cor,
    mensagem: mensagem,
    tendencia: tendencia
};

return msg;

// ==========================================
// AGROSYNK - SIMULAÇÃO CONTÍNUA DE NITROGÊNIO
// DADO SIMULADO PARA DEMONSTRAÇÃO
// ==========================================

let nitrogenio = flow.get("nitrogenioSimulado");

// Valor inicial
if (nitrogenio === undefined || nitrogenio === null) {
    nitrogenio = 40.0;
}

// Pequena variação contínua
// Aproximadamente -1.0 a +1.0
let variacao = (Math.random() - 0.5) * 2;

nitrogenio = nitrogenio + variacao;

// Limites da simulação
if (nitrogenio < 30) nitrogenio = 30;
if (nitrogenio > 50) nitrogenio = 50;

// Uma casa decimal
nitrogenio = Number(nitrogenio.toFixed(1));

flow.set("nitrogenioSimulado", nitrogenio);

msg.payload = nitrogenio;
msg.topic = "Nitrogênio (Simulado)";

return msg;

// ==========================================
// AGROSYNK - SIMULAÇÃO CONTÍNUA DE FÓSFORO
// DADO SIMULADO PARA DEMONSTRAÇÃO
// ==========================================

let fosforo = flow.get("fosforoSimulado");

if (fosforo === undefined || fosforo === null) {
    fosforo = 25.0;
}

// Variação suave: aproximadamente -0.6 a +0.6
let variacao = (Math.random() - 0.5) * 1.2;

fosforo = fosforo + variacao;

// Limites da simulação
if (fosforo < 18) fosforo = 18;
if (fosforo > 32) fosforo = 32;

fosforo = Number(fosforo.toFixed(1));

flow.set("fosforoSimulado", fosforo);

msg.payload = fosforo;
msg.topic = "Fósforo (Simulado)";

return msg;

