// ==========================================
// AGROSYNK - INTERPRETAR TXT DA ESTAÇÃO
// MAPEAMENTO DOS SENSORES
//
// IMPORTANTE:
// Os nomes "umidadeSolo1" e "temperaturaSolo1"
// são mantidos por compatibilidade com o sistema,
// porém representam UMIDADE DO AR e TEMPERATURA DO AR.
// ==========================================

let texto = msg.payload;

// Converte Buffer para texto
if (Buffer.isBuffer(texto)) {
    texto = texto.toString("utf8");
}

// Verifica se o conteúdo é válido
if (typeof texto !== "string") {
    node.error("Conteúdo do TXT inválido.", msg);
    return null;
}

// Divide o arquivo em linhas
let linhas = texto
    .split(/\r?\n/)
    .map(function(linha) {
        return linha.trim();
    })
    .filter(function(linha) {
        return linha.length > 0;
    });

