            // --------------------------------

            umidadeSolo1: leitura.umidadeSolo1,

            temperaturaSolo1: leitura.temperaturaSolo1,


            // --------------------------------
            // DATA / HORA
            // --------------------------------

            dataHora: leitura.dataHora
        });

        adicionadas++;

    } else {

        duplicadas++;
    }
});


// ==========================================
// MANTER SOMENTE OS ÚLTIMOS 30 DIAS
// ==========================================

let agora = new Date();

let limite30Dias = new Date(
    agora.getTime() - (30 * 24 * 60 * 60 * 1000)
);

historico = historico.filter(function(item) {

    let dataItem = parseData(item.dataHora);

    if (dataItem === null) {
        return false;
    }

    return dataItem.getTime() >= limite30Dias.getTime();
});


// ==========================================
// ORDENAR CRONOLOGICAMENTE
// ==========================================

historico.sort(function(a, b) {

    let dataA = parseData(a.dataHora);
    let dataB = parseData(b.dataHora);

    if (dataA === null || dataB === null) {
        return 0;
    }

    return dataA.getTime() - dataB.getTime();
});


// ==========================================
// SALVAR HISTÓRICO NO FLOW
// ==========================================

flow.set("historico30dias", historico);


// ==========================================
// INFORMAÇÕES PARA OS PRÓXIMOS NÓS
// ==========================================

msg.historico30dias = historico;

msg.totalLeituras30Dias = historico.length;

msg.leiturasAdicionadas = adicionadas;

msg.leiturasDuplicadas = duplicadas;


// Mantém a leitura mais recente no payload
if (novasLeituras.length > 0) {
    msg.payload = novasLeituras[novasLeituras.length - 1];
}

return msg;

// ==========================================
// AGROSYNK - PREPARAR INSERT POSTGRESQL
