        msg
    );

    return null;
}

// ==========================================
// PREPARAR DADOS PARA O BANCO
// ==========================================

let dadosBanco = leituras.map(function(leitura) {

    return {

        // Data e hora
        data_hora: leitura.dataHora,

        // Estação
        porta_gabinete: leitura.portaGabinete,
        tensao_bateria: leitura.tensaoBateria,

        temperatura_interna: leitura.temperaturaInterna,
        umidade_interna: leitura.umidadeInterna,

        // Chuva
        chuva_acumulada: leitura.chuvaAcumulada,

        // ==================================
        // SOLO - DADOS REAIS
        // ==================================

        umidade_solo: leitura.umidadeSolo,
        temperatura_solo: leitura.temperaturaSolo,

        // ==================================
        // AR - DADOS REAIS
        // ==================================
        //
        // Apesar do nome "_solo_1" no banco:
        //
        // umidade_solo_1 = UMIDADE DO AR
        // temperatura_solo_1 = TEMPERATURA DO AR
        //
        // Mantido assim para compatibilidade.
        // ==================================

        umidade_solo_1: leitura.umidadeSolo1,
        temperatura_solo_1: leitura.temperaturaSolo1
    };
});

// Converte o conjunto de leituras para JSON
// que será enviado ao PostgreSQL
msg.params = [
    JSON.stringify(dadosBanco)
];

return msg;

// ==========================================
// AGROSYNK - RESTAURAR HISTÓRICO DO POSTGRESQL
// ==========================================

let dados = msg.payload;

if (!Array.isArray(dados)) {
    node.error("Histórico recebido do PostgreSQL é inválido.", msg);
    return null;
}

let historico = dados.map(function(item) {

    // PostgreSQL pode retornar a data como objeto Date
    let dataHora;

    if (item.data_hora instanceof Date) {
        dataHora = item.data_hora
            .toISOString()
            .replace("T", " ")
            .substring(0, 19);
    } else {
        dataHora = String(item.data_hora)
            .replace("T", " ")
            .replace("Z", "")
            .substring(0, 19);
    }

    return {
        portaGabinete: item.porta_gabinete,
        tensaoBateria: item.tensao_bateria,
        temperaturaInterna: item.temperatura_interna,
        umidadeInterna: item.umidade_interna,
        chuvaAcumulada: item.chuva_acumulada,

        umidadeSolo: item.umidade_solo,
        temperaturaSolo: item.temperatura_solo,

        umidadeSolo1: item.umidade_solo_1,
        temperaturaSolo1: item.temperatura_solo_1,

        dataHora: dataHora
    };
});

flow.set("historico30dias", historico);

// Para conferirmos no Debug
msg.payload = historico;
msg.historico30dias = historico;
msg.totalLeituras30Dias = historico.length;
msg.historicoRestaurado = true;

return msg;
